import { StyleSheet, } from 'react-native';

const styles = StyleSheet.create({
    container: {
        width: 300,
        height: 300,
        backgroundColor: 'rgba(0,0,0,0.8)',
        borderRadius: 20,
        borderWidth: 3,
        borderColor: '#356',
        position: 'absolute',
    },

    containerResultNumber: {
        flexDirection: 'row',
        justifyContent: 'space-around',
        alignItems: 'center'
    },

    textResultNumber: {
        fontSize: 40,
        color: '#fff',
        backgroundColor: '#333',
        borderBottomStartRadius: 20,
        borderBottomEndRadius: 20,
        paddingHorizontal: 20,
    },

    containerNumber: {
        flexDirection: 'row',
        justifyContent: 'space-around',
        alignItems: 'center'
    },

    textNumber: {
        fontSize: 50,
        color: '#fff'
    },

    containerButtonConcluir: {

    },

    textButtonConcluir: {

    },

    containerButtonLimpar: {

    },

    textButtonLimpar: {

    },

});
export { styles };
